// [MEDIUM_PRIORITY] UX_POLISH: UI state management
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.captureimport timber.log.Timberimport android.media.audiofx.AcousticEchoCanceler/** * NOUS — Echo Canceller (v2: Hardware-first). * * Removes NOUS's own TTS output from the microphone input so the STT engine * doesn't transcribe NOUS talking to itself. Critical for barge-in (user * speaks while NOUS is speaking). * * ## v2 Architecture (review fix #5) * * 1. Try hardware [AcousticEchoCanceler] first (Android system audio effect, *    DSP-accelerated, low latency, no manual reference-signal routing needed). * 2. If hardware AEC is unavailable on this device, fall back to a software *    AEC implementation that takes a TTS reference signal explicitly. * * Why hardware-first: WebRTC's software AEC is sensitive to audio-latency * mismatches (10–200 ms across devices) which causes feedback loops and * phantom echoes on many phones. The hardware effect has access to the * audio HAL's reference path and is far more reliable. * * ## Testability * * The pipeline depends on the [EchoCanceller] interface, so unit tests * inject a fake. The two concrete implementations are thin wrappers around * Android / native effects and are exercised by instrumentation tests. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§5 Audio Capture Pipeline</a> */sealed interface EchoCanceller {    /**     * Process one audio chunk.     *     * @param micInput     raw mic audio (16 kHz, 16-bit PCM, 20 ms = 320 samples).     * @param ttsReference TTS audio currently being played (reference signal),     *                      or `null` when NOUS is silent. Hardware AEC ignores     *                      this (it taps the HAL reference path internally);     *                      software AEC uses it as the cancellation reference.     * @return clean audio with TTS echo removed (same format as input).     */    fun cancelEcho(micInput: ShortArray, ttsReference: ShortArray?): ShortArray    /** Whether this instance is using the hardware-accelerated path. */    val isHardwareAccelerated: Boolean    /** Release native resources. Idempotent. */    fun release()    // ──────────────────────────────────────────────────────────────────────    /**     * No-op echo canceller — passes audio through unchanged.     *     * Used when neither hardware nor software AEC is available (rare), or in     * unit tests that don't care about echo.     */    class Noop : EchoCanceller {        override fun cancelEcho(micInput: ShortArray, ttsReference: ShortArray?): ShortArray = micInput        override val isHardwareAccelerated: Boolean = false        override fun release() = Unit    }    // ──────────────────────────────────────────────────────────────────────    /**     * Factory — picks the best available [EchoCanceller] for this device.     *     * Order of preference:     *  1. [HardwareAec] — if [AcousticEchoCanceler] is available & created OK.     *  2. [softwareFallback] — caller-supplied (WebRTC wrapper or test fake).     *  3. [Noop] — last resort.     */    class Factory {        fun create(            audioSessionId: Int,            softwareFallback: EchoCanceller = Noop(),        ): EchoCanceller {            val hardware = HardwareAec.tryCreate(audioSessionId)            if (hardware != null) {                Timber.tag(TAG).i("Hardware AEC available — using AcousticEchoCanceler.")                return hardware            }            Timber.tag(TAG).w("Hardware AEC unavailable — falling back to software AEC.")            return softwareFallback        }        private companion object {            private const val TAG = "EchoCanceller"        }    }    // ──────────────────────────────────────────────────────────────────────    /**     * Hardware AEC backed by [AcousticEchoCanceler].     *     * The hardware effect taps the audio HAL's reference path internally —     * callers don't need to feed the TTS signal in. We still accept     * [ttsReference] in [cancelEcho] for API symmetry; it's ignored.     */    class HardwareAec private constructor(        private val effect: AcousticEchoCanceler,    ) : EchoCanceller {        override val isHardwareAccelerated: Boolean = true        override fun cancelEcho(micInput: ShortArray, ttsReference: ShortArray?): ShortArray {            // AcousticEchoCanceler operates on the audio session — it modifies            // the recording in place via the AudioFlinger chain. The data we            // read from AudioRecord is already echo-cancelled, so we return            // the input unchanged here.            //            // (Calling effect.setParameter() per chunk would be wrong — the            // effect is attached to the session, not to individual buffers.)            return micInput        }        override fun release() {            runCatching { effect.release() }        }        companion object {            /** Returns a HardwareAec if the effect is available on this device, else null. */            fun tryCreate(audioSessionId: Int): HardwareAec? {                if (!AcousticEchoCanceler.isAvailable()) return null                val effect = runCatching {                    AcousticEchoCanceler.create(audioSessionId)                }.getOrNull() ?: return null                // Enable immediately — AudioRecord must be running for the                // effect to attach, but enabling now is harmless and means we                // don't drop the first chunk.                val status = runCatching { effect.setEnabled(true) }.getOrDefault(                    android.media.audiofx.AudioEffect.SUCCESS + 1 /* sentinel */                )                if (status != android.media.audiofx.AudioEffect.SUCCESS) {                    runCatching { effect.release() }                    return null                }                return HardwareAec(effect)            }        }    }}